import { Object3D, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} imageUrl
 * @property {Object} atlas
 * @property {Object} atlas.sourceRect
 * @property {number} atlas.sourceRect.width
 * @property {number} atlas.sourceRect.height
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 * @property {Array<Object>} cinematicPrimitives
 * @property {Array<Object>} behavior
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} textureLoader - has a synchronous load(url) returning THREE.Texture
 * @property {Object} primitives - map of primitive functions
 * @property {Function} [emit] - optional event emitter
 */

/**
 * Creates a textured plane node with hover lift and click emit behavior.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Compute aspect from atlas source rect if provided
  const srcRect = (config.atlas && config.atlas.sourceRect) || {};
  const width = srcRect.width || 512;
  const height = srcRect.height || 320;
  const aspect = width / height;

  // Geometry and material
  const geometry = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);
  mesh.frustumCulled = false; // always render as UI element

  // Container object to hold transforms and handlers
  const node = new Object3D();
  node.add(mesh);

  // Apply transforms from config
  if (Array.isArray(config.position)) node.position.set(...config.position);
  if (Array.isArray(config.rotation)) node.rotation.set(...config.rotation);
  if (Array.isArray(config.scale)) node.scale.set(...config.scale);

  // Store base Y for hover animation
  const baseY = node.position.y;

  // GSAP timelines containers
  let hoverTimeline = null;
  let clickTimeline = null;

  // Hover handlers
  function onHoverEnter() {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(node.position, {
      y: baseY + 0.15,
      duration: 0.15,
      ease: 'power3.out',
    });
  }

  function onHoverLeave() {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(node.position, {
      y: baseY,
      duration: 0.15,
      ease: 'power3.out',
    });
  }

  // Click handler
  function onClick() {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-journal.select');
    }
  }

  // Attach handlers to userData
  node.userData.handlers = {
    hoverEnter: onHoverEnter,
    hoverLeave: onHoverLeave,
    click: onClick,
  };

  // Apply cinematic primitives listed in config
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(node, prim.params);
      }
    });
  }

  // Cleanup routine
  node.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();
    geometry.dispose();
    material.dispose();
    if (texture && typeof texture.dispose === 'function') texture.dispose();
  };

  return node;
}
